// Returns compact records so the agent context stays small.
const abstractOf = (index) => {
  if (!index) return '';
  const words = [];
  for (const [word, positions] of Object.entries(index)) for (const p of positions) words[p] = word;
  return words.join(' ').slice(0, 600);
};
const works = ($input.first().json.results ?? []).map((w) => ({
  openalex_id: w.id,
  doi: w.doi ? w.doi.replace('https://doi.org/', '') : null,
  title: w.title,
  authors: (w.authorships ?? []).slice(0, 6).map((a) => a.author?.display_name).filter(Boolean),
  year: w.publication_year,
  venue: w.primary_location?.source?.display_name ?? null,
  cited_by: w.cited_by_count ?? 0,
  pdf_url: w.best_oa_location?.pdf_url ?? null,
  landing_url: w.best_oa_location?.landing_page_url ?? w.primary_location?.landing_page_url ?? null,
  is_retracted: Boolean(w.is_retracted),
  abstract: abstractOf(w.abstract_inverted_index),
}));
return [{ json: { query: $('Start').first().json.query, count: works.length, works } }];
